function binaryTreePaths(root) {
  const paths = [];

  function dfs(node, path) {
    const current = path === '' ? String(node.val) : path + '->' + node.val;
    if (!node.left && !node.right) {
      paths.push(current);
      return;
    }
    if (node.left) {
      dfs(node.left, current);
    }
    if (node.right) {
      dfs(node.right, current);
    }
  }

  dfs(root, '');
  return paths;
}

