function binaryTreePaths(root) {
  // Record every node's parent with an explicit stack, then climb from each leaf back to the root.
  const parent = new Map([[root, null]]);
  const leaves = [];
  const stack = [root];
  while (stack.length) {
    const node = stack.pop();
    const kids = [node.left, node.right].filter(Boolean);
    if (kids.length === 0) leaves.push(node);
    for (const kid of kids) { parent.set(kid, node); stack.push(kid); }
  }
  return leaves.map(leaf => {
    const values = [];
    for (let node = leaf; node; node = parent.get(node)) values.push(node.val);
    return values.reverse().join('->');
  });
}

