function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const count = size === 'large' ? 90 + pick(11) : 1 + pick(12);
  const span = size === 'large' || rand() < 0.5 ? 100 : 3;
  const value = () => pick(2 * span + 1) - span;
  const shape = rand();
  const nodes = [{ val: value(), left: null, right: null }];
  while (nodes.length < count) {
    const node = { val: value(), left: null, right: null };
    // Mostly random shapes, sometimes long chains so paths get deep.
    const parent = shape < 0.3 ? nodes[Math.max(0, nodes.length - 1 - pick(2))] : nodes[pick(nodes.length)];
    const side = rand() < 0.5 ? 'left' : 'right';
    if (parent[side]) continue;
    parent[side] = node;
    nodes.push(node);
  }
  const out = [];
  const queue = [nodes[0]];
  for (let q = 0; q < queue.length; q++) {
    const node = queue[q];
    out.push(node ? node.val : null);
    if (node) queue.push(node.left, node.right);
  }
  while (out[out.length - 1] === null) out.pop();
  return [out];
}
